import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from forma_a import P, armar  # noqa: E402
C=Path(__file__).resolve().parents[4]/'contenido'/'04-medio/examenes'
Q=[]
def q(sec,en,ops,l,ex,oa,pts=1):
    tipo="Varias correctas" if len(l)>1 else "Alternativas"
    cab=f"**{{n}}.** *({tipo})* " if pts==1 else f"**{{n}}.** *({tipo}, {pts} puntos)* "
    Q.append(P(sec,cab,en,ops,l,ex,oa,{"tipo":tipo}))
def vf(en,v,ex,oa): Q.append(P("","**{n}.** *(Verdadero o falso)* ",en,[],"V" if v else "F",ex,oa,{"clave":"Verdadero" if v else "Falso","tipo":"Verdadero o falso"}))
SIT=lambda t,preg,palabra="situación": f"Lee la siguiente {palabra}:\n\n> \"{t}\"\n\n{preg}"
q("## Módulo 3: Ambiente y Sostenibilidad\n\n### OA N°2 — Proyectos locales de protección y uso sostenible de recursos naturales (Preguntas 1 a 13)\n\n","Una comuna instala paneles solares en los techos de sus escuelas públicas. ¿Qué beneficio sostenible principal tiene esta medida?",
 ["Aumenta el consumo de electricidad de las escuelas durante la noche","*Genera energía renovable y reduce el uso de electricidad de fuentes contaminantes","Elimina la necesidad de mantener los edificios de las escuelas","Permite que las escuelas vendan los paneles a otras comunas cada año"],"b","Los paneles solares generan energía renovable en el mismo lugar: reducen la electricidad que se compra a la red, parte de la cual proviene de fuentes que emiten gases de efecto invernadero.","OA 2")
vf("Un proyecto de reciclaje en un liceo puede evaluarse midiendo, antes y después, la cantidad de residuos que deja de enviar al vertedero.",True,"Verdadero. Medir los residuos antes y después del proyecto entrega evidencia concreta de su efecto, en lugar de basarse solo en impresiones.","OA 2")
q("","Una caleta acuerda una veda temporal para la extracción de locos durante su período reproductivo. ¿Qué objetivo cumple esta medida?",
 ["Aumentar el precio del loco para que los pescadores ganen más ese año","Prohibir para siempre la pesca artesanal en toda la costa de la región","*Permitir que la población se reproduzca y se recupere, asegurando la pesca futura","Reemplazar la pesca de locos por la crianza de salmones en la caleta"],"c","La veda protege el período reproductivo: así la población de locos se recupera y la caleta puede seguir pescando en el futuro, un uso sostenible del recurso.","OA 2",2)
q("","¿Qué es lo correcto hacer con el aceite de cocina usado en un hogar que participa en un proyecto de cuidado del agua?",
 ["*Guardarlo en botellas cerradas y llevarlo a un punto de reciclaje","Botarlo por el lavaplatos con abundante agua caliente","Enterrarlo en el patio, cerca de las plantas del jardín","Mezclarlo con cloro antes de botarlo por el desagüe"],"a","El aceite usado contamina el agua y tapa las cañerías: debe guardarse y llevarse a un punto de reciclaje, donde puede transformarse, por ejemplo, en biodiésel.","OA 2")
q("","Una junta de vecinos quiere plantar árboles en una plaza de una ciudad de la zona central, con veranos secos. ¿Qué criterio es más adecuado para elegir las especies?",
 ["Elegir las especies más baratas del vivero de la comuna, sin importar su origen ni cuánta agua necesitan","Elegir solo especies exóticas, porque siempre crecen más rápido que todas las demás especies del país","Elegir especies que necesiten mucho riego, para que la plaza se vea siempre verde incluso en pleno verano","*Preferir especies nativas adaptadas al clima local, que requieren menos riego y favorecen la biodiversidad"],"d","Las especies nativas adaptadas al clima seco necesitan menos agua y sirven de alimento y refugio a la fauna local: es la opción más sostenible para la plaza.","OA 2",2)
q("",SIT("Un humedal urbano de Valdivia, hogar de aves como el cisne de cuello negro, recibe basura y rellenos de tierra para construir viviendas en sus bordes.","¿Qué acciones forman parte de un proyecto sostenible para proteger este humedal? Marca **todas** las correctas."),
 ["Solicitar su protección oficial como humedal urbano ante la autoridad","Organizar limpiezas y actividades de educación ambiental con los vecinos","Rellenar una parte del humedal para construir un estacionamiento","Monitorear periódicamente la calidad del agua y la presencia de aves"],"abd","Pedir su protección legal, educar y limpiar con la comunidad y monitorear el agua y las aves protegen el humedal; rellenarlo destruye el hábitat.","OA 2",3)
vf("Quemar los restos de poda en el patio es una forma sostenible de eliminarlos, porque la madera es un material natural.",False,"Falso. La quema libera humo, material particulado y gases que contaminan el aire; los restos de poda pueden compostarse o triturarse para usarlos como cobertura del suelo.","OA 2")
q("","Una minera del desierto de Atacama necesita grandes cantidades de agua. ¿Qué alternativa reduce la presión sobre los acuíferos de la zona?",
 ["Extraer más agua de los ríos del altiplano durante el verano","*Usar agua de mar desalinizada y recircular el agua de sus procesos","Comprar el agua potable de las ciudades cercanas a la faena","Perforar nuevos pozos en los salares para aumentar la extracción"],"b","El agua de mar desalinizada y la recirculación del agua de los procesos reducen la extracción de agua dulce de los acuíferos, escasa en el desierto.","OA 2")
q("","¿Por qué compostar los residuos orgánicos de un colegio es una práctica sostenible?",
 ["*Porque los transforma en abono y evita que generen metano en el vertedero","Porque elimina por completo todos los residuos plásticos del colegio","Porque permite quemar los residuos sin producir humo ni olores","Porque reemplaza la necesidad de reciclar el papel y el vidrio"],"a","Al compostar, la materia orgánica se convierte en abono para el huerto o las áreas verdes, y deja de descomponerse en el vertedero, donde produce metano.","OA 2",2)
q("",SIT("Una comunidad costera de la Región de Los Lagos encuentra cada semana botellas, bolsas y redes de plástico en sus playas.","¿Qué medidas son pertinentes para reducir el plástico en esas playas? Marca **todas** las correctas."),
 ["Quemar el plástico recogido en la misma playa","Promover bolsas reutilizables en el comercio local","Instalar puntos limpios para separar y reciclar","Hacer limpiezas comunitarias que registren los residuos encontrados"],"bcd","Reducir las bolsas desechables, reciclar en puntos limpios y registrar los residuos en limpiezas comunitarias atacan el problema; quemar plástico contamina el aire.","OA 2",3)
q("","¿Qué ventaja ambiental tiene desplazarse en bicicleta en vez de en auto dentro de una ciudad?",
 ["Aumenta la congestión de las calles en las horas punta","Consume más combustible por cada kilómetro recorrido","*No genera emisiones directas y reduce la congestión","Obliga a construir más estacionamientos en el centro"],"c","La bicicleta no quema combustible, por lo que no genera emisiones directas, y ocupa menos espacio que un auto, lo que reduce la congestión.","OA 2")
q("","Una comunidad recupera un estero contaminado plantando vegetación nativa en sus orillas. ¿Qué efecto tiene esta medida?",
 ["Aumenta la erosión de las orillas y la cantidad de sedimentos en el agua","Elimina por completo la necesidad de tratar las aguas servidas de la zona","Impide que cualquier animal se acerque al estero durante todo el año","*Ayuda a filtrar contaminantes, estabiliza las orillas y entrega hábitat a la fauna"],"d","La vegetación nativa de ribera retiene sedimentos y contaminantes, evita la erosión de las orillas y ofrece refugio y alimento a la fauna del estero.","OA 2",2)
q("",SIT("Un liceo de Talca evalúa si su nuevo huerto escolar es un proyecto sostenible.","¿Qué criterios indican que el huerto es sostenible? Marca **todas** las correctas."),
 ["Usa compost producido con los residuos orgánicos del propio liceo","Aplica grandes cantidades de pesticidas químicos cada semana","Riega por goteo para ahorrar agua","Involucra a estudiantes, apoderados y vecinos en su cuidado"],"acd","El compost propio, el riego por goteo y la participación de la comunidad hacen que el huerto sea sostenible; el uso intensivo de pesticidas daña el suelo, el agua y la biodiversidad.","OA 2",3)
q("### OA N°3 — Cambio climático: efectos en los ecosistemas y mitigación (Preguntas 14 a 25)\n\n","¿Cuál de los siguientes hechos es una evidencia del cambio climático observada en Chile?",
 ["*El aumento de la temperatura media y la megasequía de la zona central","La existencia de la cordillera de los Andes en el límite oriental","El cambio de estaciones entre el verano y el invierno de cada año","Los terremotos que ocurren a lo largo de toda la costa del país"],"a","El alza de la temperatura media y la megasequía de la zona central, que comenzó alrededor de 2010, se asocian al cambio climático; los terremotos y las estaciones tienen otras causas.","OA 3")
vf("El cambio climático se refiere solo a que en verano hace más calor que antes.",False,"Falso. El cambio climático incluye el aumento de la temperatura media global, pero también cambios en las lluvias, en el nivel del mar, en los glaciares y en la frecuencia de eventos extremos.","OA 3")
q("","Una ciudad costera proyecta un aumento del nivel del mar en las próximas décadas. ¿Qué medidas de **adaptación** son pertinentes? Marca **todas** las correctas.",
 ["Evitar nuevas construcciones en las zonas más bajas de la costa","Reforzar las defensas costeras en los sectores más expuestos","Restaurar dunas y humedales costeros que amortiguan las marejadas","Ignorar las proyecciones, porque siempre tienen algún grado de incertidumbre"],"abc","Planificar para no construir en zonas bajas, reforzar defensas y restaurar dunas y humedales reducen los daños; que las proyecciones tengan incertidumbre no justifica ignorarlas.","OA 3",2)
q("","¿Por qué el derretimiento del hielo del océano Ártico puede acelerar el calentamiento global?",
 ["Porque el agua del deshielo es más caliente que el aire que la rodea","Porque el hielo derretido libera oxígeno que calienta la atmósfera","*Porque el hielo refleja la luz solar, y al derretirse el océano oscuro absorbe más calor","Porque sin hielo los barcos pueden navegar y emiten todo el calor del planeta"],"c","El hielo blanco refleja gran parte de la luz solar; el océano, más oscuro, la absorbe y se calienta más, lo que derrite más hielo: es una retroalimentación que acelera el calentamiento.","OA 3")
q("",SIT("Entre 2010 y 2022, la zona central de Chile vivió una megasequía, con lluvias muy por debajo de lo normal durante varios años seguidos. Muchos agricultores perdieron cosechas y varias comunas dependieron de camiones aljibe.","¿Qué opción distingue correctamente una medida de adaptación y una de mitigación frente a este problema?"),
 ["Adaptación: usar más energía generada con carbón. Mitigación: regar todos los cultivos por inundación","*Adaptación: tecnificar el riego para usar menos agua. Mitigación: reemplazar combustibles fósiles por energías renovables","Adaptación: talar bosques nativos para sembrar más. Mitigación: aumentar el uso de autos particulares","Las dos medidas son iguales, porque adaptación y mitigación significan exactamente lo mismo en este caso"],"b","Adaptarse es ajustarse a los efectos (tecnificar el riego ante la sequía); mitigar es atacar las causas, reduciendo las emisiones (reemplazar combustibles fósiles por energías renovables).","OA 3",3)
vf("Plantar bosque nativo puede contribuir a mitigar el cambio climático, porque los árboles absorben CO₂ de la atmósfera mientras crecen.",True,"Verdadero. Los árboles capturan CO₂ en la fotosíntesis y lo almacenan en su madera; por eso conservar y plantar bosques es una medida de mitigación.","OA 3")
q("","¿Por qué reemplazar las centrales termoeléctricas a carbón por energía solar y eólica es una medida de **mitigación** del cambio climático?",
 ["Porque permite construir más centrales a carbón en otras regiones","Porque aumenta la cantidad de electricidad que se pierde en los cables","Porque protege a las ciudades costeras del aumento del nivel del mar","*Porque reduce las emisiones de gases de efecto invernadero que causan el calentamiento"],"d","Mitigar es reducir las causas del cambio climático: la energía solar y la eólica generan electricidad sin quemar carbón, por lo que emiten muchos menos gases de efecto invernadero.","OA 3",2)
q("",SIT("Distribución aproximada de las emisiones de gases de efecto invernadero de Chile por sector (datos de ejemplo, basados en el Inventario Nacional): energía 77 %; agricultura 10 %; procesos industriales 7 %; residuos 6 %.","A partir de la información, ¿qué afirmaciones son correctas? Marca **todas** las correctas.","información"),
 ["El sector energía es el que más gases de efecto invernadero emite","Los residuos emiten más gases que el sector energía","Reducir el uso de combustibles fósiles en la energía tiene un gran potencial de mitigación","La agricultura no emite ningún gas de efecto invernadero"],"ac","El sector energía concentra la mayor parte de las emisiones (77 %), así que reducir los combustibles fósiles en él tiene gran potencial; los residuos emiten mucho menos y la agricultura sí emite (10 %).","OA 3",3)
q("","¿Qué gas de efecto invernadero se libera principalmente al quemar combustibles fósiles como el petróleo, el carbón y el gas?",
 ["*El dióxido de carbono (CO₂)","El oxígeno molecular (O₂)","El nitrógeno molecular (N₂)","El gas noble helio (He)"],"a","La combustión del carbono de los combustibles fósiles produce dióxido de carbono (CO₂), el principal gas de efecto invernadero de origen humano.","OA 3")
q("","¿Por qué los océanos se están volviendo más ácidos a causa del aumento del CO₂ en la atmósfera?",
 ["Porque el agua del mar se evapora más rápido y deja la sal concentrada","*Porque el océano absorbe CO₂, que al disolverse forma ácido carbónico","Porque los barcos vierten ácido en el mar cuando cruzan el océano","Porque el derretimiento de los glaciares agrega ácido al agua de mar"],"b","Los océanos absorben parte del CO₂ de la atmósfera; al disolverse en el agua forma ácido carbónico, que baja el pH del mar y afecta a organismos con conchas y corales.","OA 3",2)
q("",SIT("Temperatura media anual de una ciudad de la zona central, por década (datos de ejemplo): década de 1970: 14,0 °C; de 1990: 14,4 °C; de 2010: 14,9 °C; de 2020: 15,1 °C.","¿Qué conclusión es más adecuada a partir de estos datos?","información"),
 ["Que la temperatura de la ciudad bajó en cada década del período registrado, por lo que no hay calentamiento","Que los datos de esta ciudad prueban por sí solos que todo el planeta se calentó exactamente 1,1 °C en el período","*Que hay una tendencia al aumento, coherente con el calentamiento, aunque una sola ciudad no basta para generalizar al planeta","Que las variaciones de temperatura de la ciudad no tienen ninguna relación posible con el cambio climático global"],"c","Los datos muestran un aumento sostenido (de 14,0 a 15,1 °C), coherente con el calentamiento; pero los datos de una sola ciudad no bastan para concluir sobre todo el planeta.","OA 3",3)
q("","¿Qué acciones personales contribuyen a mitigar el cambio climático? Marca **todas** las correctas.",
 ["Usar el transporte público o la bicicleta en lugar del auto","Dejar las luces y los aparatos encendidos cuando no se usan","Reducir el desperdicio de alimentos en el hogar","Reparar los objetos en lugar de comprar otros nuevos"],"acd","Usar transporte público o bicicleta, no desperdiciar alimentos y reparar objetos reducen las emisiones asociadas al combustible y a la producción; dejar aparatos encendidos aumenta el consumo de energía.","OA 3",3)
